#include "db_bridge.h"
#include "libdbbridge.h"  // generated by `go build -buildmode=c-archive`

#include <stdexcept>
#include <vector>

namespace stream {

namespace {
constexpr size_t kErrLen = 1024;
}

DbRecordStream::DbRecordStream(const std::string &addr, uint32_t start,
                               uint32_t end, uint32_t max_records,
                               uint32_t record_bytes,
                               uint32_t connect_timeout_sec)
    : record_bytes_(record_bytes) {
  std::vector<char> err(kErrLen, 0);
  handle_ = DBStreamOpen(const_cast<char *>(addr.c_str()), start, end,
                         max_records, record_bytes, connect_timeout_sec,
                         err.data(), err.size());
  if (handle_ < 0)
    throw std::runtime_error("database stream open failed: " +
                             std::string(err.data()));
}

DbRecordStream::~DbRecordStream() { DBStreamClose(handle_); }

void DbRecordStream::read_exact(uint8_t *dst, uint64_t count) {
  std::vector<char> err(kErrLen, 0);
  while (count > 0) {
    const int64_t n = DBStreamRead(handle_, dst, count, err.data(), err.size());
    if (n < 0)
      throw std::runtime_error("database stream failed: " +
                               std::string(err.data()));
    if (n == 0) throw std::runtime_error("database stream ended early");
    dst += static_cast<uint64_t>(n) * record_bytes_;
    count -= static_cast<uint64_t>(n);
  }
}

void expected_record(uint32_t index, uint32_t record_bytes, uint8_t *dst) {
  DBExpectedRecord(index, record_bytes, dst);
}

} // namespace stream
